import { createEffect, createMemo, omit, onSettled } from 'solid-js';
import type { JSX } from '@solidjs/web';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

export type AnimatedContentWipe = 'none' | 'up' | 'down' | 'left' | 'right' | 'center';
export type AnimatedContentStaggerFrom = 'start' | 'end' | 'center' | 'edges' | 'random';

export interface AnimatedContentProps extends Omit<
  JSX.HTMLAttributes<HTMLDivElement>,
  'onAnimationStart' | 'style' | 'children'
> {
  children?: JSX.Element;
  container?: Element | string | null;
  distance?: number;
  direction?: 'vertical' | 'horizontal';
  reverse?: boolean;
  duration?: number;
  ease?: string;
  initialOpacity?: number;
  animateOpacity?: boolean;
  scale?: number;
  blur?: number;
  rotate?: number;
  tilt?: number;
  wipe?: AnimatedContentWipe;
  threshold?: number;
  delay?: number;
  stagger?: number;
  staggerFrom?: AnimatedContentStaggerFrom;
  trigger?: 'scroll' | 'mount';
  once?: boolean;
  scrub?: boolean | number;
  disappearAfter?: number;
  disappearDuration?: number;
  disappearEase?: string;
  onStart?: () => void;
  onComplete?: () => void;
  onDisappearanceComplete?: () => void;
  className?: string;
  style?: JSX.CSSProperties;
}

type Settings = {
  container: Element | string | null | undefined;
  distance: number;
  direction: 'vertical' | 'horizontal';
  reverse: boolean;
  duration: number;
  ease: string;
  initialOpacity: number;
  animateOpacity: boolean;
  scale: number;
  blur: number;
  rotate: number;
  tilt: number;
  wipe: AnimatedContentWipe;
  threshold: number;
  delay: number;
  stagger: number;
  staggerFrom: AnimatedContentStaggerFrom;
  trigger: 'scroll' | 'mount';
  once: boolean;
  scrub: boolean | number;
  disappearAfter: number;
  disappearDuration: number;
  disappearEase: string;
};

const WIPES: Record<string, string> = {
  up: 'linear-gradient(to top, #000 calc(var(--ac-wipe) * 140% - 40%), transparent calc(var(--ac-wipe) * 140%))',
  down: 'linear-gradient(to bottom, #000 calc(var(--ac-wipe) * 140% - 40%), transparent calc(var(--ac-wipe) * 140%))',
  left: 'linear-gradient(to left, #000 calc(var(--ac-wipe) * 140% - 40%), transparent calc(var(--ac-wipe) * 140%))',
  right: 'linear-gradient(to right, #000 calc(var(--ac-wipe) * 140% - 40%), transparent calc(var(--ac-wipe) * 140%))',
  center:
    'radial-gradient(farthest-corner at 50% 50%, #000 calc(var(--ac-wipe) * 140% - 40%), transparent calc(var(--ac-wipe) * 140%))'
};

const OWN_KEYS = [
  'children',
  'container',
  'distance',
  'direction',
  'reverse',
  'duration',
  'ease',
  'initialOpacity',
  'animateOpacity',
  'scale',
  'blur',
  'rotate',
  'tilt',
  'wipe',
  'threshold',
  'delay',
  'stagger',
  'staggerFrom',
  'trigger',
  'once',
  'scrub',
  'disappearAfter',
  'disappearDuration',
  'disappearEase',
  'onStart',
  'onComplete',
  'onDisappearanceComplete',
  'className',
  'style'
] as const;

export default function AnimatedContent(props: AnimatedContentProps) {
  let ref: HTMLDivElement | undefined;
  let current: Settings | null = null;
  let rebuild: (() => void) | null = null;
  let callbacks: Pick<AnimatedContentProps, 'onStart' | 'onComplete' | 'onDisappearanceComplete'> = {};
  const rest = omit(props, ...OWN_KEYS);

  const settings = createMemo<Settings>(() => ({
    container: props.container,
    distance: props.distance ?? 100,
    direction: props.direction ?? 'vertical',
    reverse: props.reverse ?? false,
    duration: props.duration ?? 0.8,
    ease: props.ease ?? 'power3.out',
    initialOpacity: props.initialOpacity ?? 0,
    animateOpacity: props.animateOpacity ?? true,
    scale: props.scale ?? 1,
    blur: props.blur ?? 0,
    rotate: props.rotate ?? 0,
    tilt: props.tilt ?? 0,
    wipe: props.wipe ?? 'none',
    threshold: props.threshold ?? 0.1,
    delay: props.delay ?? 0,
    stagger: props.stagger ?? 0,
    staggerFrom: props.staggerFrom ?? 'start',
    trigger: props.trigger ?? 'scroll',
    once: props.once ?? true,
    scrub: props.scrub ?? false,
    disappearAfter: props.disappearAfter ?? 0,
    disappearDuration: props.disappearDuration ?? 0.5,
    disappearEase: props.disappearEase ?? 'power3.in'
  }));

  createEffect(
    () => ({
      onStart: props.onStart,
      onComplete: props.onComplete,
      onDisappearanceComplete: props.onDisappearanceComplete
    }),
    value => {
      callbacks = value;
    }
  );

  createEffect(settings, value => {
    if (value === current) return;
    current = value;
    rebuild?.();
  });

  const setup = (el: HTMLDivElement, s: Settings) => {
    const {
      container,
      distance,
      direction,
      reverse,
      duration,
      ease,
      initialOpacity,
      animateOpacity,
      scale,
      blur,
      rotate,
      tilt,
      wipe,
      threshold,
      delay,
      stagger,
      staggerFrom,
      trigger,
      once,
      scrub,
      disappearAfter,
      disappearDuration,
      disappearEase
    } = s;

    let scroller: Element | string | null = container || document.getElementById('snap-main-container') || null;
    if (typeof scroller === 'string') scroller = document.querySelector(scroller);

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;

    return gsap.context(() => {
      const targets: Element[] = stagger > 0 && el.children.length ? Array.from(el.children) : [el];
      const horizontal = direction === 'horizontal';
      const axis = horizontal ? 'x' : 'y';
      const sign = reverse ? -1 : 1;
      const mask = WIPES[wipe];

      gsap.set(el, { visibility: 'visible' });

      if (reduce) {
        callbacks.onComplete?.();
        return;
      }

      const from: gsap.TweenVars = {
        [axis]: distance * sign,
        scale,
        opacity: animateOpacity ? initialOpacity : 1
      };
      const to: gsap.TweenVars = {
        [axis]: 0,
        scale: 1,
        opacity: 1,
        duration,
        ease
      };

      if (blur > 0) {
        from.filter = `blur(${blur}px)`;
        to.filter = 'blur(0px)';
      }
      if (rotate) {
        from.rotation = rotate * sign;
        to.rotation = 0;
      }
      if (tilt) {
        const tiltAxis = horizontal ? 'rotationY' : 'rotationX';
        from[tiltAxis] = horizontal ? -tilt * sign : tilt * sign;
        to[tiltAxis] = 0;
        from.transformPerspective = 900;
        to.transformPerspective = 900;
      }
      if (mask) {
        gsap.set(targets, { maskImage: mask, webkitMaskImage: mask });
        from['--ac-wipe'] = 0;
        to['--ac-wipe'] = 1;
      }
      if (stagger > 0) to.stagger = { each: stagger, from: staggerFrom };

      const settle = () => {
        if (scrub) return;
        gsap.set(targets, { clearProps: mask ? 'filter,transform,maskImage,webkitMaskImage' : 'filter,transform' });
      };

      const disappear = () => {
        if (disappearAfter <= 0) return;
        const out: gsap.TweenVars = {
          [axis]: -distance * sign,
          scale: 0.8,
          opacity: animateOpacity ? initialOpacity : 0,
          delay: disappearAfter,
          duration: disappearDuration,
          ease: disappearEase,
          onComplete: () => callbacks.onDisappearanceComplete?.()
        };
        if (blur > 0) out.filter = `blur(${blur}px)`;
        if (stagger > 0) out.stagger = { each: stagger, from: staggerFrom };
        gsap.to(targets, out);
      };

      const tl = gsap.timeline({
        paused: true,
        onStart: () => callbacks.onStart?.(),
        onComplete: () => {
          callbacks.onComplete?.();
          settle();
          if (once && !scrub) disappear();
        }
      });
      tl.fromTo(targets, from, to, scrub ? 0 : Math.max(delay, 0));

      if (trigger === 'mount') {
        tl.play();
        return;
      }

      const start = `top ${(1 - threshold) * 100}%`;

      if (scrub) {
        ScrollTrigger.create({
          trigger: el,
          scroller,
          start,
          end: `top ${Math.max((1 - threshold) * 100 - 45, 5)}%`,
          scrub: scrub === true ? true : Math.max(Number(scrub) || 0, 0.01),
          animation: tl
        });
        return;
      }

      ScrollTrigger.create({
        trigger: el,
        scroller,
        start,
        once,
        onEnter: () => tl.play(),
        onLeaveBack: once
          ? undefined
          : () => {
              if (mask) gsap.set(targets, { maskImage: mask, webkitMaskImage: mask });
              tl.reverse();
            }
      });
    }, el);
  };

  onSettled(() => {
    const el = ref;
    if (!el) return;
    current = settings();
    let ctx = setup(el, current);
    rebuild = () => {
      ctx.revert();
      if (current) ctx = setup(el, current);
    };
    return () => {
      rebuild = null;
      ctx.revert();
    };
  });

  return (
    <div {...rest} ref={el => (ref = el)} class={props.className} style={{ visibility: 'hidden', ...props.style }}>
      {props.children}
    </div>
  );
}
